using System.Data;using System.Data.Common;using AiCare.Application;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Storage;
namespace AiCare.Api;
[ApiController,Authorize(Roles="Administrator")][Route("api/phase1/finance/accounting/connections")]
public sealed class AccountingSyncControlController(CareDbContext db,ITenantContext tenant,ICurrentUserContext user):ControllerBase
{
 [HttpPost("{provider}/sync-state")]
 public async Task<IActionResult>SetState(string provider,AccountingSyncStateRequest r,CancellationToken t){if(r.Environment is not ("Test" or "Production"))return BadRequest(new{message="Environment must be Test or Production."});if(r.Enable&&r.Confirmation!="ENABLE OUTBOUND ACCOUNTING SYNC")return BadRequest(new{message="Type ENABLE OUTBOUND ACCOUNTING SYNC to confirm financial-data transmission."});var changed=await Exec("update accounting_connections set sync_enabled=@enabled,environment=@environment where organization_id=@org and provider=@provider and status='Active'",c=>{Add(c,"enabled",r.Enable);Add(c,"environment",r.Environment);Add(c,"provider",provider);},t);if(changed==0)return NotFound();db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),r.Enable?"ACCOUNTING_SYNC_ENABLED":"ACCOUNTING_SYNC_DISABLED",user.UserName,"AccountingConnection",null,DateTimeOffset.UtcNow,tenant.OrganizationId,tenant.BranchId??TenantDefaults.BranchId));await db.SaveChangesAsync(t);return NoContent();}
 [HttpGet("sync-state")]public async Task<IActionResult>States(CancellationToken t){var rows=new List<object>();await using var c=await Cmd("select provider,status,environment,sync_enabled,external_tenant_id from accounting_connections where organization_id=@org order by provider",t);await using var reader=await c.ExecuteReaderAsync(t);while(await reader.ReadAsync(t))rows.Add(new{provider=reader.GetString(0),status=reader.GetString(1),environment=reader.GetString(2),syncEnabled=reader.GetBoolean(3),externalTenantId=reader.GetString(4)});return Ok(rows);}
 async Task<int>Exec(string s,Action<DbCommand>b,CancellationToken t){await using var c=await Cmd(s,t);b(c);return await c.ExecuteNonQueryAsync(t);}async Task<DbCommand>Cmd(string s,CancellationToken t){var n=db.Database.GetDbConnection();if(n.State!=ConnectionState.Open)await n.OpenAsync(t);var c=n.CreateCommand();c.Transaction=db.Database.CurrentTransaction?.GetDbTransaction();c.CommandText=s;Add(c,"org",tenant.OrganizationId);return c;}static void Add(DbCommand c,string n,object?v){if(c.Parameters.Contains(n))return;var p=c.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;c.Parameters.Add(p);}
}
public sealed record AccountingSyncStateRequest(bool Enable,string Environment,string Confirmation);
